//! Oracle comparison: verify Rust LSST FrameSet transforms match C library output.

use ast_core::coords::PointSet;
use ast_core::from_native_string;
use ast_core::mappings::Mapping;

fn load_lsst() -> Box<dyn Mapping> {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/native/reference/lsst.ast"
    ))
    .unwrap();
    from_native_string(&text).unwrap().into_mapping().unwrap()
}

/// C library forward transform results for 10 test points.
/// Generated by running astTran2 on the C-compiled lsst.ast.
const C_FORWARD: [(f64, f64); 10] = [
    (9.226876571347123e-01, -4.934535221983469e-01),
    (9.226876650180645e-01, -4.934535138181675e-01),
    (9.226876729014163e-01, -4.934535054379883e-01),
    (9.226876807847685e-01, -4.934534970578089e-01),
    (9.226876886681202e-01, -4.934534886776299e-01),
    (9.226876965514714e-01, -4.934534802974509e-01),
    (9.226877044348222e-01, -4.934534719172721e-01),
    (9.226877123181734e-01, -4.934534635370933e-01),
    (9.226877202015241e-01, -4.934534551569146e-01),
    (9.226877280848743e-01, -4.934534467767361e-01),
];

#[test]
fn lsst_forward_matches_c() {
    let mapping = load_lsst();

    let mut rows = Vec::new();
    for i in 0..10 {
        rows.push(vec![100.0 + i as f64 * 0.01, 200.0 + i as f64 * 0.005]);
    }
    let pts = PointSet::from_rows(rows);
    let out = mapping.transform(&pts, true).unwrap();

    for i in 0..10 {
        let (cx, cy) = C_FORWARD[i];
        let rx = out.point(i)[0];
        let ry = out.point(i)[1];
        let dx = (rx - cx).abs();
        let dy = (ry - cy).abs();
        assert!(
            dx < 1e-12,
            "point {i} x: rust={rx:.15e}, c={cx:.15e}, diff={dx:.2e}"
        );
        assert!(
            dy < 1e-12,
            "point {i} y: rust={ry:.15e}, c={cy:.15e}, diff={dy:.2e}"
        );
    }
}

#[test]
fn lsst_inverse_round_trip() {
    let mapping = load_lsst();

    let mut rows = Vec::new();
    for i in 0..10 {
        rows.push(vec![100.0 + i as f64 * 0.01, 200.0 + i as f64 * 0.005]);
    }
    let pts = PointSet::from_rows(rows);

    // Forward then inverse should recover original (within NR tolerance)
    let fwd = mapping.transform(&pts, true).unwrap();
    let inv = mapping.transform(&fwd, false).unwrap();

    for i in 0..10 {
        let ox = pts.point(i)[0];
        let oy = pts.point(i)[1];
        let rx = inv.point(i)[0];
        let ry = inv.point(i)[1];
        let dx = (rx - ox).abs();
        let dy = (ry - oy).abs();
        // C library achieves ~1e-10 round-trip accuracy
        assert!(
            dx < 1e-6,
            "point {i} x round-trip: orig={ox}, recovered={rx}, diff={dx:.2e}"
        );
        assert!(
            dy < 1e-6,
            "point {i} y round-trip: orig={oy}, recovered={ry}, diff={dy:.2e}"
        );
    }
}
